 max-width: 1600px;
 margin: 0 auto;
 padding: 24px;
 display: flex;
 flex-direction: column;
 gap: 24px;
 background: #0a0e1a;
 min-height: 100vh;
 color: #e2e8f0;
 font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.fraud-app *,
.fraud-app *::before,
.fraud-app *::after {
 box-sizing: border-box;
 margin: 0;
 padding: 0;
}

.fraud-app .fcard {
 background: #131a2e;
 border: 1px solid #1e2a45;
 border-radius: 14px;
 padding: 24px;
}

.fraud-app .fcard--glow {
 box-shadow: 0 0 20px rgba(0, 200, 150, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.03);
}

.fraud-app .fsection-title {
 font-size: 11px;
 font-weight: 700;
 letter-spacing: 1.5px;
 color: #94a3b8;
 text-transform: uppercase;
 margin-bottom: 16px;
}

.fraud-row {
 display: grid;
 gap: 24px;
}

.fraud-row-2 {
 grid-template-columns: 1fr 1fr;
}

@keyframes fraud-pulse {
 0%, 100% {
 opacity: 1;
 transform: scale(1);
 }
 50% {
 opacity: 0.5;
 transform: scale(1.3);
 }
}
@keyframes fraud-fade-in {
 from {
 opacity: 0;
 transform: translateY(8px);
 }
 to {
 opacity: 1;
 transform: translateY(0);
 }
}
.fraud-app .fade-in {
 animation: fraud-fade-in 0.4s ease-out forwards;
